  "accLinkFailed": "Tengillinn gæti verið útrunninn eða þegar notaður. Opnaðu Aðgang til að skrá þig inn eða biðja um nýjan póst.",
  "privFooter": "Persónuvernd og geymsla",
  "privTitle": "Persónuvernd og vafrageymsla",
  "privClose": "Loka persónuverndartilkynningu",
  "privWho": "Hver ber ábyrgð?",
  "privWhat": "Hvað við notum og hvers vegna",
  "privStorage": "Vafrageymsla",
  "privOther": "Aðrir núverandi eiginleikar",
  "privProviders": "Þjónustuveitendur og flutningur milli landa",
  "privRetention": "Varðveisla og eyðing",
  "privRights": "Réttindi þín",
  "noticeReopen": "Tilkynning um geymslu",
  "noticeLabel": "Tilkynning um vafrageymslu",
  "noticeText": "Cook notar vafrageymslu fyrir þá matreiðslu- og innskráningareiginleika sem þú notar. Engin geymsla fyrir auglýsingar eða greiningu er bætt við.",
  "noticeClose": "Loka tilkynningu um geymslu",
  "privDraftLabel": "Drög – uppfært 28. október 2026.",
  "privDraft": "Verið er að prófa aðgangseiginleikana. Upplýsingar um rekstraraðila og þjónustu hér að neðan þarf að fylla út fyrir opnun.",
  "privWho1": "Cook er rekið af [löglegt nafn og póstfang rekstraraðila]. Hafðu samband við [netfang vegna persónuverndar] með spurningar og beiðnir um persónuvernd. Þessar upplýsingar þarf að fylla út áður en skráning opnar.",
  "privWhat1": "Þegar þú stofnar aðgang notum við netfangið þitt, auðkenni aðgangs, gögn um auðkenningu með lykilorði og staðfestingarstöðu til að veita og verja aðganginn þinn. Auðkenningarþjónustan meðhöndlar lykilorð sem örugg tætigildi; Cook geymir engin læsileg lykilorð. Við vistum skipulag eldhússins, valið tungumál, þema og mælieiningar til að endurheimta stillingarnar þínar í öllum tækjum. Netfang og lykilorð eru nauðsynleg fyrir aðgang; þú getur skoðað uppskriftir án aðgangs.",
  "privWhat2": "Vinnsla aðgangs og stillinga er nauðsynleg til að veita aðgangsþjónustuna sem þú biður um (b-liður 1. mgr. 6. gr. persónuverndarreglugerðarinnar, GDPR). Takmörkuð gögn vegna öryggis og varna gegn misnotkun kunna að vera unnin á grundvelli lögmætra hagsmuna (f-liður 1. mgr. 6. gr.), að því marki sem það er nauðsynlegt og að undangengnu hagsmunamati. Póstar um staðfestingu og endurstillingu lykilorðs eru þjónustuskilaboð, ekki markaðssetning. Aðgangseiginleikinn bætir hvorki við auglýsingum né greiningu.",
  "privStorage1": "Cook notar sessionStorage til að flytja eldhúsið, framvindu eldamennsku og val þitt milli síðna í sama flipa. Þegar þú ert innskráð(ur) geymir það einnig innskráningarlotuna þína. Vafrinn hreinsar þetta yfirleitt þegar lotu flipans lýkur, en endurheimt lotu í vafranum getur haldið því. Útskráning hreinsar flipagögn Cook. Lokun tilkynningar um geymslu er aðeins geymd í þeim flipa. Eigin forskriftir Cook setja engar vafrakökur. Hýsingar- eða þjónustuaðilar kunna að vera með eigin öryggisvinnslu sem þarf að skrá fyrir opnun.",
  "privStorage2": "Í lagi og lokunarhnappurinn á tilkynningu um geymslu loka aðeins tilkynningunni. Þeir heimila ekki greiningu, auglýsingar eða aðra valkvæða rakningu. Öll ónauðsynleg geymsla í framtíðinni krefst sérstaks vals áður en hún hefst, þar sem jafnauðvelt er að hafna og afturkalla.",
  "privOther1": "Núverandi talaðgerð uppskriftalistans biður country.is um áætlað land út frá IP-tölunni þinni til að velja tungumál talgreiningar. Ef þú notar hljóðnemagreiningu kann vafrinn að senda hljóð til talgreiningarþjónustu sinnar. Þú getur líka slegið inn hráefni. Fara þarf yfir þessa þjónustuaðila, stefnur þeirra og lagagrundvöll þessara eiginleika fyrir opnun.",
  "privProviders1": "Fyrirhugaður aðgangsþjónustuaðili: Supabase (hýst PostgreSQL og auðkenning), með völdu gagnagrunnssvæði innan ESB. Tölvupóstþjónusta: [þjónustuaðili]. Vefhýsing: [þjónustuaðili]. Rekstraraðili þarf að staðfesta raunverulega þjónustuaðila, vinnslusamninga, undirvinnsluaðila, staðsetningu skráa og hvers kyns flutning út fyrir EES. Gagnagrunnssvæði innan ESB útilokar ekki eitt og sér flutning milli landa. Þar sem við á skal tilgreina viðeigandi ákvörðun um fullnægjandi vernd eða samningsbundnar verndarráðstafanir og hvernig fá megi afrit.",
  "privRetention1": "Stillingar aðgangs eru geymdar á meðan aðgangurinn er virkur. Þú getur óskað eftir eyðingu í gegnum persónuverndartengiliðinn hér að ofan. Fyrir opnun þarf rekstraraðili að ákveða hvernig eyðingarbeiðnum er svarað, hvenær óstaðfestir aðgangar renna út og hve lengi öryggisskrár og afrit eru geymd. Eydd gögn kunna að vera áfram í aðgangsstýrðum afritum þar til skráður varðveislutími rennur út.",
  "privRights1": "Eftir því sem skilyrði leyfa getur þú óskað eftir aðgangi, leiðréttingu, eyðingu, takmörkun eða flutningi gagna, eða andmælt vinnslu sem byggist á lögmætum hagsmunum. Hafðu samband við rekstraraðila hér að ofan; beiðnum er yfirleitt svarað innan mánaðar og lögmæt framlenging er útskýrð. Þú getur kvartað til eftirlitsyfirvalds, meðal annars ungversku NAIH á naih.hu. Cook notar ekki stillingar aðgangs til sjálfvirkra ákvarðana sem hafa réttaráhrif eða sambærileg veruleg áhrif.",
