  "privCommunity": "Ef þú velur notandanafn birtist það við opinberar athugasemdir þínar. Athugasemdir og dagsetning þeirra eru sýnilegar öllum, ásamt stjörnunum sem þú gafst uppskriftinni; meðaleinkunnir eru sýndar án nafna. Uppskriftasagan, persónulegar athugasemdir og innkaupalistinn eru einkamál þín. Ef þú eyðir aðganginum er allt þetta fjarlægt.",
